WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/29.0/connection.js")}
{!REQUIRESCRIPT("/soap/ajax/29.0/apex.js")}
var result = sforce.apex.execute("YhatQuery","getOutput",{yhat_id:"{!
 WC_Credit_Decision__c.YHat_Id__c}"});
if (result[0] == "Error") {
    result = []
    result[0] = '{"Error" : "Could not get model output"}';
}
var obj = JSON.parse(result[0]);
var json = JSON.stringify(obj, undefined, 4);

var z = json.replace(/("(\\u[a-zA-Z0-9]{4}|\\[^u]|[^\\"])*"(\s*:)?|\b(true|false|null)\b|-?\d+(?:\.\d*)?(?:[eE][+\-]?\d+)?)/g, function (match) {
        var cls = 'number';
        if (/^"/.test(match)) {
            if (/:$/.test(match)) {
                cls = 'key';
            } else {
                cls = 'string';
            }
        } else if (/true|false/.test(match)) {
            cls = 'boolean';
        } else if (/null/.test(match)) {
            cls = 'null';
        }
        return '<span class="' + cls + '">' + match + '</span>';
    });
var x = window.open();
x.document.body.appendChild(document.createElement('pre')).innerHTML=z;
var style = x.document.createElement('style');
style.type = 'text/css';

var css = "pre {padding: 5px; margin: 5px; }.string { color: green; }.number { color: darkorange; }.boolean { color: blue; }.null { color: magenta; }.key { color: red; }";

style.appendChild(document.createTextNode(css));

x.document.head.appendChild(style);
